import { NextResponse } from "next/server";
import Stripe from "stripe";
import {
  buildCustomizationDescription,
  resolveCheckoutItems,
  SHIPPING_PRICE,
  type CheckoutItemInput,
} from "@/lib/checkout-pricing";
import { getStripeServer } from "@/lib/stripe-server";

interface CheckoutRequestBody {
  items?: CheckoutItemInput[];
  acceptedSalesPolicy?: boolean;
}

export const runtime = "nodejs";

function toCents(amount: number) {
  return Math.round(amount * 100);
}

export async function POST(request: Request) {
  try {
    const body = (await request.json()) as CheckoutRequestBody;
    const items = body.items ?? [];

    if (body.acceptedSalesPolicy !== true) {
      return NextResponse.json(
        { error: "Vous devez accepter la politique de vente finale avant le paiement." },
        { status: 400 }
      );
    }

    if (!Array.isArray(items) || items.length === 0) {
      return NextResponse.json({ error: "Le panier est vide." }, { status: 400 });
    }

    const resolvedItems = resolveCheckoutItems(items);
    const shipping = resolvedItems.length > 0 ? SHIPPING_PRICE : 0;

    const currency = (process.env.STRIPE_CURRENCY ?? "cad").toLowerCase();
    const origin = request.headers.get("origin") ?? process.env.NEXT_PUBLIC_APP_URL ?? "http://localhost:3000";
    const allowedCountries = (process.env.STRIPE_ALLOWED_COUNTRIES ?? "CA,US")
      .split(",")
      .map((country) => country.trim().toUpperCase())
      .filter(Boolean);
    const stripe = getStripeServer();

    const orderId = crypto.randomUUID();

    const lineItems: Stripe.Checkout.SessionCreateParams.LineItem[] = resolvedItems.map((item) => ({
      quantity: item.quantity,
      price_data: {
        currency,
        unit_amount: toCents(item.unitPrice),
        product_data: {
          name: item.name,
          description: buildCustomizationDescription(item.customization),
        },
      },
    }));

    if (shipping > 0) {
      lineItems.push({
        quantity: 1,
        price_data: {
          currency,
          unit_amount: toCents(shipping),
          product_data: {
            name: "Livraison",
          },
        },
      });
    }

    const session = await stripe.checkout.sessions.create({
      mode: "payment",
      line_items: lineItems,
      success_url: `${origin}/success?session_id={CHECKOUT_SESSION_ID}`,
      cancel_url: `${origin}/cancel`,
      locale: "fr",
      billing_address_collection: "required",
      shipping_address_collection: {
        allowed_countries: allowedCountries.length > 0 ? allowedCountries : ["CA"],
      },
      customer_creation: "always",
      invoice_creation: {
        enabled: true,
        invoice_data: {
          description: `Commande ${orderId}`,
          metadata: {
            orderId,
            salesPolicyAccepted: "true",
            salesPolicyVersion: "2026-11-22",
          },
        },
      },
      automatic_tax: {
        enabled: true,
      },
      excluded_payment_method_types: ["klarna", "paypal"],
      metadata: {
        orderId,
        salesPolicyAccepted: "true",
        salesPolicyVersion: "2026-11-22",
      },
      client_reference_id: orderId,
    });

    if (!session.url) {
      return NextResponse.json({ error: "Session Stripe invalide (URL manquante)." }, { status: 500 });
    }

    return NextResponse.json({ checkoutUrl: session.url });
  } catch (error) {
    const message = error instanceof Error ? error.message : "Erreur Stripe inconnue.";
    return NextResponse.json({ error: message }, { status: 500 });
  }
}

import { NextResponse } from "next/server";
import Stripe from "stripe";
import {
  buildCustomizationDescription,
  resolveCheckoutItems,
  type CheckoutItemInput,
} from "@/lib/checkout-pricing";
import { getStripeServer } from "@/lib/stripe-server";
import { getDeliveryOption, type DeliveryMethod } from "@/lib/delivery";
import { getProductImageUrl } from "@/lib/products";

interface CheckoutRequestBody {
  items?: CheckoutItemInput[];
  acceptedSalesPolicy?: boolean;
  deliveryMethod?: DeliveryMethod;
}

export const runtime = "nodejs";

function toCents(amount: number) {
  return Math.round(amount * 100);
}

export async function POST(request: Request) {
  try {
    const body = (await request.json()) as CheckoutRequestBody;
    const items = body.items ?? [];

    if (body.acceptedSalesPolicy !== true) {
      return NextResponse.json(
        { error: "Vous devez accepter la politique de vente finale avant le paiement." },
        { status: 400 }
      );
    }

    if (!Array.isArray(items) || items.length === 0) {
      return NextResponse.json({ error: "Le panier est vide." }, { status: 400 });
    }

    const resolvedItems = resolveCheckoutItems(items);
    const delivery = getDeliveryOption(body.deliveryMethod);

    if (!delivery) {
      return NextResponse.json(
        { error: "Veuillez choisir un mode de livraison." },
        { status: 400 }
      );
    }

    const shipping = resolvedItems.length > 0 ? delivery.price : 0;

    const currency = (process.env.STRIPE_CURRENCY ?? "cad").toLowerCase();
    const origin = request.headers.get("origin") ?? process.env.NEXT_PUBLIC_APP_URL ?? "http://localhost:3000";
    const stripe = getStripeServer();

    const orderId = crypto.randomUUID();

    const lineItems: Stripe.Checkout.SessionCreateParams.LineItem[] = resolvedItems.map((item) => ({
      quantity: item.quantity,
      price_data: {
        currency,
        unit_amount: toCents(item.unitPrice),
        product_data: {
          name: item.name,
          description: buildCustomizationDescription(item.customization),
          metadata: {
            productId: String(item.id),
            image: getProductImageUrl(item.id),
          },
        },
      },
    }));

    if (shipping > 0) {
      lineItems.push({
        quantity: 1,
        price_data: {
          currency,
          unit_amount: toCents(shipping),
          product_data: {
            name: "Livraison",
            description: delivery.label,
          },
        },
      });
    }

    const session = await stripe.checkout.sessions.create({
      mode: "payment",
      line_items: lineItems,
      success_url: `${origin}/success?session_id={CHECKOUT_SESSION_ID}`,
      cancel_url: `${origin}/cancel`,
      locale: "fr",
      billing_address_collection: "required",
      custom_fields:
        delivery.id === "mikawaii-express"
          ? [
              {
                key: "delivery_sector",
                label: { type: "custom", custom: "Secteur Mikawaii-Express" },
                type: "dropdown",
                dropdown: {
                  options: [
                    { label: "Limoilou", value: "limoilou" },
                    { label: "Beauport", value: "beauport" },
                    { label: "Charlesbourg", value: "charlesbourg" },
                  ],
                },
              },
            ]
          : undefined,
      shipping_address_collection:
        delivery.id === "mikawaii-express" || delivery.id === "canada-post"
          ? { allowed_countries: ["CA"] }
          : undefined,
      customer_creation: "always",
      invoice_creation: {
        enabled: true,
        invoice_data: {
          description: `Commande ${orderId}`,
          metadata: {
            orderId,
            salesPolicyAccepted: "true",
            salesPolicyVersion: "2026-11-22",
            deliveryMethod: delivery.id,
            deliveryLabel: delivery.label,
            deliveryPrice: shipping.toFixed(2),
          },
        },
      },
      automatic_tax: {
        enabled: true,
      },
      excluded_payment_method_types: ["klarna", "paypal"],
      metadata: {
        orderId,
        salesPolicyAccepted: "true",
        salesPolicyVersion: "2026-11-22",
        deliveryMethod: delivery.id,
        deliveryLabel: delivery.label,
        deliveryPrice: shipping.toFixed(2),
      },
      client_reference_id: orderId,
    });

    if (!session.url) {
      return NextResponse.json({ error: "Session Stripe invalide (URL manquante)." }, { status: 500 });
    }

    return NextResponse.json({ checkoutUrl: session.url });
  } catch (error) {
    const message = error instanceof Error ? error.message : "Erreur Stripe inconnue.";
    return NextResponse.json({ error: message }, { status: 500 });
  }
}

import { headers } from "next/headers";
import { NextResponse } from "next/server";
import Stripe from "stripe";
import { sendBuyerOrderConfirmation, sendPaidOrderNotification, type EmailOrderItem, type StoredOrder } from "@/lib/order-notification";
import { getStripeServer } from "@/lib/stripe-server";
export const runtime = "nodejs";
function parseCustomization(description?: string | null) {
  if (!description) return undefined;
  const parts = Object.fromEntries(description.split(" | ").map((part) => {
    const index = part.indexOf(": ");
    return index >= 0 ? [part.slice(0, index), part.slice(index + 2)] : [part, ""];
  }));
  const scoop = Number(parts["Scoop"]);
  return {
    scoopCount: scoop === 2 ? 2 : 1,
    notes: parts["Preferences"] ?? "",
    surpriseStar: parts["Etoile surprise"] === "Oui",
    socialMediaVideo: parts["Video reseaux"] === "Oui",
    recipientName: parts["Destinataire"]?.trim() || undefined,
  };
}
export async function POST(request: Request) {
  const webhookSecret = process.env.STRIPE_WEBHOOK_SECRET;
  if (!webhookSecret) return NextResponse.json({ error: "Configuration Stripe manquante (STRIPE_WEBHOOK_SECRET)." }, { status: 500 });
  const stripe = getStripeServer();
  const payload = await request.text();
  const signature = (await headers()).get("stripe-signature");
  if (!signature) return NextResponse.json({ error: "Signature Stripe manquante." }, { status: 400 });
  let event: Stripe.Event;
  try {
    event = stripe.webhooks.constructEvent(payload, signature, webhookSecret);
  } catch (error) {
    return NextResponse.json({ error: error instanceof Error ? error.message : "Signature Stripe invalide." }, { status: 400 });
  }
  try {
    if (event.type === "checkout.session.completed" || event.type === "checkout.session.async_payment_succeeded") {
      const eventSession = event.data.object as Stripe.Checkout.Session;
      const session = await stripe.checkout.sessions.retrieve(eventSession.id, {
        expand: ["line_items", "line_items.data.price.product"],
      });
      const orderId = session.metadata?.orderId ?? session.client_reference_id ?? session.id;
      const buyerEmail = session.customer_details?.email ?? session.customer_email ?? undefined;
      const shipping = session.collected_information?.shipping_details;
      const shippingAddress = shipping ? {
        name: shipping.name ?? undefined,
        line1: shipping.address.line1 ?? undefined,
        line2: shipping.address.line2 ?? undefined,
        city: shipping.address.city ?? undefined,
        state: shipping.address.state ?? undefined,
        postalCode: shipping.address.postal_code ?? undefined,
        country: shipping.address.country ?? undefined,
      } : undefined;
      const items: EmailOrderItem[] = [];
      for (const line of session.line_items?.data ?? []) {
        const product = typeof line.price?.product === "object" ? line.price.product : null;
        const name = product && "name" in product ? product.name : line.description ?? "Article";
        if (name === "Livraison") continue;
        const quantity = line.quantity ?? 1;
        const unitAmount = line.price?.unit_amount ?? Math.round((line.amount_total ?? 0) / quantity);
        items.push({
          id: Number(line.price?.metadata?.productId ?? 0),
          name,
          unitPrice: unitAmount / 100,
          quantity,
          customization: parseCustomization(product && "description" in product ? product.description : line.description),
        });
      }
      const shippingAmount = (session.total_details?.amount_shipping ?? 0) / 100;
      const currency = session.currency ?? process.env.STRIPE_CURRENCY ?? "cad";
      const now = new Date().toISOString();
      const order: StoredOrder = {
        id: orderId,
        status: "paid",
        currency,
        shippingAmount,
        createdAt: now,
        updatedAt: now,
        items,
        buyerEmail,
        shippingAddress,
        stripeSessionId: session.id,
        stripeCustomerId: typeof session.customer === "string" ? session.customer : undefined,
        stripePaymentIntentId: typeof session.payment_intent === "string" ? session.payment_intent : undefined,
        stripeInvoiceId: typeof session.invoice === "string" ? session.invoice : undefined,
        stripePaymentStatus: session.payment_status,
      };
      const paymentIntentId = typeof session.payment_intent === "string" ? session.payment_intent : undefined;
      if (buyerEmail && paymentIntentId) {
        try { await stripe.paymentIntents.update(paymentIntentId, { receipt_email: buyerEmail }); } catch (error) {
          console.warn("[webhook] Could not request Stripe receipt:", error);
        }
      }
      const customerId = typeof session.customer === "string" ? session.customer : undefined;
      if (customerId) {
        try { await stripe.customers.update(customerId, { preferred_locales: ["fr-CA", "fr"] }); } catch (error) {
          console.warn("[webhook] Could not set customer locale:", error);
        }
      }
      const invoiceId = order.stripeInvoiceId;
      if (invoiceId) {
        try {
          let invoice = await stripe.invoices.retrieve(invoiceId);
          if (invoice.status !== "paid") {
            try { invoice = await stripe.invoices.pay(invoiceId, { paid_out_of_band: true }); } catch (error) {
              console.warn("[webhook] Invoice could not be forced paid:", error);
            }
          }
          order.stripeInvoicePdfUrl = invoice.invoice_pdf ?? undefined;
          order.stripeInvoiceHostedUrl = invoice.hosted_invoice_url ?? undefined;
        } catch (error) {
          console.warn("[webhook] Could not retrieve invoice:", error);
        }
      }
      await sendPaidOrderNotification(order);
      if (buyerEmail) await sendBuyerOrderConfirmation(order, buyerEmail);
    }
    return NextResponse.json({ received: true });
  } catch (error) {
    return NextResponse.json({ error: error instanceof Error ? error.message : "Erreur webhook inconnue." }, { status: 500 });
  }
}

